def mat(a):return '['+';'.join(' '.join(format(float(v),'.17g') for v in row) for row in a)+']'
def rows(name,cols):
 with (W/'inputs/paper/tables'/f'{name}.csv').open() as f:r=list(csv.DictReader(f))
 return mat([[x[c] for c in cols] for x in r])
data="% Frozen numeric data: see inputs/source_map.json for original hashes.\n"
