registry=[]
for entry in m['figures']:
 n=entry['figure_number'];stem=Path(entry['file']).stem
 if n not in S:continue
 source=', '.join(entry['source_files'])
 text=f"% Figure {n}: {source}\n% Native GUI only; saved data/formula drawing. No upstream experiment.\nbase='{B}'; addpath(base);run([base '/plot_data.m']);\nblue=[.141 .388 .627];orange=[.851 .510 .169];gray=[.451 .482 .525];red=[.714 .271 .271];pale=[.90 .94 .98];\nf=figure('Name','F{n:02d} {stem}','Color','white');\n"+S[n]+f"\nfid=fopen('{W}/logs/fig{n:02d}_native.txt','w');fprintf(fid,'DRAW_SCRIPT_COMPLETE figure={n}\\n');fclose(fid);\n"
 (B/'figures'/f'draw_{stem}.m').write_text(text)
 registry.append({'number':n,'stem':stem,'script':str(B/'figures'/f'draw_{stem}.m'),'export':str(W/'figures'/f'{stem}.png')})
(W/'gui_queue.json').write_text(json.dumps(registry,ensure_ascii=False,indent=2))
(B/'run_one_figure.m').write_text("function run_one_figure(n)\nbase='"+str(B)+"';\nswitch n\n"+''.join(f"case {x['number']};run([base '/figures/draw_{x['stem']}.m']);\n" for x in registry)+"otherwise;error('Skipped: missing original data');\nend\nend\n")
print(f'{len(registry)} native figure scripts generated; no graphics rendered by Python.')
